    /** `accounts.accounts`, kept, its rows UniFFI's. */
    fun accounts(): View<AccountLine> = typed(AccountLineView(peer, "accounts.accounts", "null"))

    /** `accounts.close_account`: its intent's id. */
    fun closeAccount(input: CloseAccount): String = peer.mutate("accounts.close_account", input.json())

    /** `accounts.open_account`: its intent's id. */
    fun openAccount(input: OpenAccount): String = peer.mutate("accounts.open_account", input.json())

    /** `accounts.rename_account`: its intent's id. */
    fun renameAccount(input: RenameAccount): String = peer.mutate("accounts.rename_account", input.json())

    /** `banks.add_accounts`: its intent's id. */
    fun addAccounts(input: BankName): String = peer.mutate("banks.add_accounts", input.json())

    /** `banks.answer`: its intent's id. */
    fun answer(input: Answer): String = peer.mutate("banks.answer", input.json())

    /** `banks.asks`, kept, its rows UniFFI's. */
    fun asks(): View<AskLine> = typed(AskLineView(peer, "banks.asks", "null"))

    /** `banks.banks`, kept, its rows UniFFI's. */
    fun banks(): View<BankLine> = typed(BankLineView(peer, "banks.banks", "null"))

    /** `banks.connect`: its intent's id. */
    fun connect(): String = peer.mutate("banks.connect", "null")

    /** `banks.disconnect`: its intent's id. */
    fun disconnect(input: BankName): String = peer.mutate("banks.disconnect", input.json())

    /** `banks.failed`: its intent's id. */
    fun failed(input: BankFailed): String = peer.mutate("banks.failed", input.json())

    /** `banks.ignore`: its intent's id. */
    fun ignore(input: IgnoreLinked): String = peer.mutate("banks.ignore", input.json())

    /** `banks.import`: its intent's id. */
    fun import(input: Import): String = peer.mutate("banks.import", input.json())

    /** `banks.link`: its intent's id. */
    fun link(input: LinkAccount): String = peer.mutate("banks.link", input.json())

    /** `banks.linked`, kept, its rows UniFFI's. */
    fun linked(): View<LinkedLine> = typed(LinkedLineView(peer, "banks.linked", "null"))

    /** `banks.open`: its intent's id. */
    fun open(input: OpenLinked): String = peer.mutate("banks.open", input.json())

    /** `banks.reconnect`: its intent's id. */
    fun reconnect(input: BankName): String = peer.mutate("banks.reconnect", input.json())

    /** `banks.retired`: its intent's id. */
    fun retired(input: BankName): String = peer.mutate("banks.retired", input.json())

    /** `banks.sync`: its intent's id. */
    fun sync(): String = peer.mutate("banks.sync", "null")

    /** `budget.assign`: its intent's id. */
    fun assign(input: Assign): String = peer.mutate("budget.assign", input.json())

    /** `budget.auto_assign`: its intent's id. */
    fun autoAssign(input: AutoAssign): String = peer.mutate("budget.auto_assign", input.json())

    /** `budget.groups`, kept, its rows UniFFI's. */
    fun groups(): View<GroupLine> = typed(GroupLineView(peer, "budget.groups", "null"))

    /** `budget.month`, kept, its rows UniFFI's. */
    fun month(input: Month): View<BudgetLine> = typed(BudgetLineView(peer, "budget.month", input.json()))

    /** `budget.move_money`: its intent's id. */
    fun moveMoney(input: MoveMoney): String = peer.mutate("budget.move_money", input.json())

    /** `budget.setup`: its intent's id. */
    fun setup(): String = peer.mutate("budget.setup", "null")

    /** `budget.spending`, kept, its rows UniFFI's. */
    fun spending(input: Month): View<SpendingLine> = typed(SpendingLineView(peer, "budget.spending", input.json()))

    /** `budget.summary`, kept, its rows UniFFI's. */
    fun summary(input: Month): View<Summary> = typed(SummaryView(peer, "budget.summary", input.json()))

    /** `categories.add_category`: its intent's id. */
    fun addCategory(input: AddCategory): String = peer.mutate("categories.add_category", input.json())

    /** `categories.add_group`: its intent's id. */
    fun addGroup(input: AddGroup): String = peer.mutate("categories.add_group", input.json())

    /** `categories.delete_category`: its intent's id. */
    fun deleteCategory(input: DeleteCategory): String = peer.mutate("categories.delete_category", input.json())

    /** `categories.delete_group`: its intent's id. */
    fun deleteGroup(input: DeleteGroup): String = peer.mutate("categories.delete_group", input.json())

    /** `categories.hide_category`: its intent's id. */
    fun hideCategory(input: HideCategory): String = peer.mutate("categories.hide_category", input.json())

    /** `categories.hide_group`: its intent's id. */
    fun hideGroup(input: HideGroup): String = peer.mutate("categories.hide_group", input.json())

    /** `categories.move_category`: its intent's id. */
    fun moveCategory(input: MoveCategory): String = peer.mutate("categories.move_category", input.json())

    /** `categories.move_group`: its intent's id. */
    fun moveGroup(input: MoveGroup): String = peer.mutate("categories.move_group", input.json())

    /** `categories.rename_category`: its intent's id. */
    fun renameCategory(input: RenameCategory): String = peer.mutate("categories.rename_category", input.json())

    /** `categories.rename_group`: its intent's id. */
    fun renameGroup(input: RenameGroup): String = peer.mutate("categories.rename_group", input.json())

    /** `categories.set_target`: its intent's id. */
    fun setTarget(input: SetTarget): String = peer.mutate("categories.set_target", input.json())

    /** `role.grant`: its intent's id. */
    fun grant(input: Grant): String = peer.mutate("role.grant", input.json())

    /** `role.revoke`: its intent's id. */
    fun roleRevoke(input: Grant): String = peer.mutate("role.revoke", input.json())

    /** `session.current`. */
    fun current(): SignIn? = J.opt(J.parse(peer.query("session.current", "null"))) { v0 -> SignIn.of(v0) }

    /** `session.mine`, kept. */
    fun mine(): View<SignIn> = View(peer.view("session.mine", "null")) { j -> SignIn.of(j) }

    /** `session.revoke`: its intent's id. */
    fun sessionRevoke(input: Revoke): String = peer.mutate("session.revoke", input.json())

    /** `transactions.add_transaction`: its intent's id. */
    fun addTransaction(input: AddTransaction): String = peer.mutate("transactions.add_transaction", input.json())

    /** `transactions.approve`: its intent's id. */
    fun approve(input: Txns): String = peer.mutate("transactions.approve", input.json())

    /** `transactions.categorize`: its intent's id. */
    fun categorize(input: Categorize): String = peer.mutate("transactions.categorize", input.json())

    /** `transactions.delete_transactions`: its intent's id. */
    fun deleteTransactions(input: Txns): String = peer.mutate("transactions.delete_transactions", input.json())

    /** `transactions.edit_transaction`: its intent's id. */
    fun editTransaction(input: EditTransaction): String = peer.mutate("transactions.edit_transaction", input.json())

    /** `transactions.inbox`, kept, its rows UniFFI's. */
    fun inbox(): View<TxnLine> = typed(TxnLineView(peer, "transactions.inbox", "null"))

    /** `transactions.payees`, kept, its rows UniFFI's. */
    fun payees(): View<PayeeLine> = typed(PayeeLineView(peer, "transactions.payees", "null"))

    /** `transactions.reconcile`: its intent's id. */
    fun reconcile(input: Reconcile): String = peer.mutate("transactions.reconcile", input.json())

    /** `transactions.register`, kept, its rows UniFFI's. */
    fun register(input: Register): View<TxnLine> = typed(TxnLineView(peer, "transactions.register", input.json()))

    /** `transactions.set_cleared`: its intent's id. */
    fun setCleared(input: SetCleared): String = peer.mutate("transactions.set_cleared", input.json())

    private fun typed(v: AccountLineView): View<AccountLine> = View.typed(v::rows, { v.take().let { it.update to it.rows } }, v::close)

    private fun typed(v: AskLineView): View<AskLine> = View.typed(v::rows, { v.take().let { it.update to it.rows } }, v::close)

    private fun typed(v: BankLineView): View<BankLine> = View.typed(v::rows, { v.take().let { it.update to it.rows } }, v::close)

    private fun typed(v: BudgetLineView): View<BudgetLine> = View.typed(v::rows, { v.take().let { it.update to it.rows } }, v::close)

    private fun typed(v: GroupLineView): View<GroupLine> = View.typed(v::rows, { v.take().let { it.update to it.rows } }, v::close)

    private fun typed(v: LinkedLineView): View<LinkedLine> = View.typed(v::rows, { v.take().let { it.update to it.rows } }, v::close)

    private fun typed(v: PayeeLineView): View<PayeeLine> = View.typed(v::rows, { v.take().let { it.update to it.rows } }, v::close)

    private fun typed(v: SpendingLineView): View<SpendingLine> = View.typed(v::rows, { v.take().let { it.update to it.rows } }, v::close)

    private fun typed(v: SummaryView): View<Summary> = View.typed(v::rows, { v.take().let { it.update to it.rows } }, v::close)

    private fun typed(v: TxnLineView): View<TxnLine> = View.typed(v::rows, { v.take().let { it.update to it.rows } }, v::close)
}
